#include <iostream>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int A, B, C, D;
    if (!(cin >> A >> B >> C >> D)) return 0;

    bool possible = false;
    for (int k = 1; k * D <= C; ++k) {
        int milk = C - k * D;
        if (milk >= A && milk <= B) {
            possible = true;
            break;
        }
    }

    if (possible) {
        cout << "S\n";
    } else {
        cout << "N\n";
    }

    return 0;
}
